package android.app;import android.content.*;public class PendingIntent {public static final int FLAG_UPDATE_CURRENT=1,FLAG_IMMUTABLE=2;public Intent intent;public int flags;private PendingIntent(Intent i,int f){intent=i;flags=f;}public static PendingIntent getActivity(Context c,int id,Intent i,int f){return new PendingIntent(i,f);}public static PendingIntent getService(Context c,int id,Intent i,int f){return new PendingIntent(i,f);} }